def backfill_recording_owners(apps, schema_editor):
    """Заполняет владельцев существующих мастер-записей."""
    Recording = apps.get_model('store', 'Recording')

    db_alias = schema_editor.connection.alias

    recordings = (
        Recording.objects
        .using(db_alias)
        .select_related('album')
        .all()
    )

    for recording in recordings.iterator(chunk_size=1000):
        recording.owner_id = recording.album.artist_id
        recording.save(
            using=db_alias,
            update_fields=('owner',),
        )


